import json
nodes=json.load(open('/tmp/snap2.json'))['data']['nodes']
for n in nodes:
    label=str(n.get('label') or '')
    r=n.get('rect') or {}
    if any(k in label for k in ['Profile','Home','Search','Chat','Notifications','Feeds','Following']) or n.get('type') in ('TabBar','Button'):
        print(label, n.get('type'), r, n.get('ref'))
" 2>&1 | head -30

